INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425235, 16443, 'South China Morning Post', 'en', 'Norway’s King Harald dies at 89 after 35-year reign', 'https://www.scmp.com/news/world/europe/article/3365566/norways-king-harald-dead-89', 'Norway’s King Harald has died aged 89, the palace said on Friday, his 53-year-old son Crown Prince Haakon automatically succeeding him on the throne. “It is with deep sadness that we announce that His Majesty King Harald passed away today. King Harald passed away peacefully at Oslo University Hospital on Friday, August 28 at 6.35am,” it said in a statement. The flag at the royal palace in Oslo was lowered to half mast. Prime Minister Jonas Gahr Store said he had received the news with “deep...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/8d70c1da-06ec-4cb5-80a4-fb49610ff054_ec819f76.jpg?itok=AqyA3RBL&v=1787902845', '2026-08-28T06:58:44+00:00', '2026-08-28T12:53:51.823711'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
