INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425493, 16443, 'Euronews', 'en', 'Norway''s new monarch King Haakon VIII: His life, role and challenges ahead', 'http://www.euronews.com/my-europe/2026/08/28/norways-new-monarch-king-haakon-viii-his-life-role-and-challenges-ahead', 'Norway''s monarchy dates back to King Harald Fairhair in the ninth century. When the country regained independence in 1905, three-quarters of voters backed restoring the monarchy in a national referendum.', '', '2026-08-28T09:32:58+00:00', '2026-08-28T12:54:11.339592'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
