INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422727, 16451, 'France 24', 'en', 'Spain''s Villena Treasure stolen in four-minute museum heist', 'https://www.france24.com/en/spain-s-villena-treasure-stolen-in-four-minute-museum-heist', 'Almost the entire Villena Treasure, one of Europe''s most valuable Bronze Age collections, was stolen from a museum in eastern Spain in a four-minute raid after thieves smashed through a window and bulletproof glass. Police believe several people and vehicles were involved, and suspect the thieves created a diversion by triggering an alarm at a nearby sports centre before the break-in.', 'https://s.france24.com/media/display/7bd46e22-a2bb-11f1-a715-005056bfb2b6/w:1024/p:16x9/EN-20260828-071327-071455-CS.jpg', '2026-08-28T09:04:20+00:00', '2026-08-28T12:49:23.903603'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427235, 16451, 'BBC News', 'en', 'Thieves steal 600-diamond necklace from Vienna museum in broad daylight', 'https://www.bbc.co.uk/news/articles/cqxvwpe0plro', 'Police are hunting two suspects they believe bought a ticket for the exhibition to get at the jewellery.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/1df5/live/5d837d40-a2fd-11f1-aed2-8d6da8d75094.jpg', '2026-08-28T17:29:16+00:00', '2026-08-29T00:03:08.541407'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427247, 16451, 'The Guardian', 'en', 'Egyptian queen’s 673-diamond necklace stolen in Vienna smash-and-grab raid', 'https://www.theguardian.com/artanddesign/2026/aug/28/egyptian-queen-diamond-necklace-stolen-vienna-raid', 'Police hunt two suspects after historic 200-carat piece is snatched from Austrian museum during opening hours Austrian police are hunting two men alleged to have stolen a 200-carat platinum necklace encrusted with 673 diamonds that was on loan to a museum in Vienna and once belonged to Egyptian royalty. Authorities in the capital released pictures of the suspects captured by security cameras during the heist at the Museum of Applied Arts (MAK), amid a rash of spectacular smash-and-grab thefts from European cultural institutions. Continue reading...', 'https://i.guim.co.uk/img/media/7ea385a25016498346b2081fed61a63745b04ef4/0_515_2327_1862/master/2327.jpg?width=140&quality=85&auto=format&fit=max&s=95655421ec65a4d503bfd0c301615c64', '2026-08-28T14:46:25+00:00', '2026-08-29T00:03:18.424415'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
